import sys
from collections import defaultdict, deque

def main():
    data = sys.stdin.read().split()
    p = 0
    m = int(data[p]); p += 1
    routes = []
    for _ in range(m):
        L = int(data[p]); p += 1
        routes.append([int(x) for x in data[p:p + L]])
        p += L
    s, t = int(data[p]), int(data[p + 1])
    if s == t:
        print(0)
        return
    at = defaultdict(list)
    for i, r in enumerate(routes):
        for x in r:
            at[x].append(i)
    seen_r = [False] * m
    seen_s = {s}
    dq = deque()
    for i in at.get(s, ()):
        seen_r[i] = True
        dq.append((i, 1))
    while dq:
        i, d = dq.popleft()
        for x in routes[i]:
            if x == t:
                print(d)
                return
            if x not in seen_s:
                seen_s.add(x)
                for j in at[x]:
                    if not seen_r[j]:
                        seen_r[j] = True
                        dq.append((j, d + 1))
    print(-1)

